// 玩家系統
import { reactive } from "vue";

export function player() {
    return reactive({
        name: "Abisu", //玩家名稱
        job: "",
        maxHP: 30, //最大生命值
        hp: 30, //目前生命值
        ap: 3, //行動力
        mp: 3, //魔力值

        //能力值
        attack: 0, //攻擊力
        baseAttack: 0, //原始攻擊力
        defend: 0, //護甲值
        baseDefend: 0, //原始護甲值
        critRate: 0, //暴擊率
        baseCritRate: 0, //原始爆擊率
        critDmg: 0, //暴擊傷害
        baseCritDmg: 0, //原始暴擊傷害

        //卡牌系統
        baseDeck: [],//原始卡組
        deck: [], //開局卡組
        hand: [], //手牌
        discard: [], //棄牌區

        //狀態
        buff: 0, //攻擊增強
        buffCount: 0,
        gameOver: false, //遊戲是否結束（死亡）

        //背包
        backpack: ["heal_potion"], //物品
        coin: 99999 //金幣
    });
}

//戰士
export function warrior() {
    return reactive({
        name: "warrior",
        maxHP: 50,
        hp: 50,
        ap: 3,
        mp: 0,
        baseDeck: ["atk_nomal","atk_nomal", "atk_nomal", "def_shield", "heal_bandage"],//初始牌組
    })
}

//法師
