<template>
  <div 
    class="card"
    :class="{ 'disabled': isDisabled }"
    @click="handleClick"
  >
    <img :src="card.img" class="card-bg" alt="card" />

    <div class="card-content">
      
      <div class="card-text-name">
        {{ card.name }}
      </div>

      <div class="card-text-cost" :class="costClass">
        {{ finalCost }}
      </div>

      <div class="card-text-desc">
        {{ card.desc }}
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "GameCard",
  props: {
    card: {
      type: Object,
      required: true
    }
  },
  computed: {
    isApCard() {
      return this.card.costAP !== undefined;
    },
    finalCost() {
      return this.isApCard ? this.card.costAP : this.card.costMP;
    },
    costClass() {
      return this.isApCard ? 'text-ap' : 'text-mp';
    },
    isDisabled() {
      return false; 
    }
  },
  methods: {
    handleClick() {
      this.$emit('play', this.card);
    }
  }
};
</script>

<style scoped>
.card {
  width: 150px;
  height: 220px;
  position: relative; /* 讓內部的 absolute 對齊這裡 */
  cursor: pointer;
  transition: transform 0.2s;
  user-select: none;
  background-color: transparent; /* 背景透明 */
  border-radius: 15px;
  overflow: hidden;
}

.card:hover {
  transform: scale(1.1);
  z-index: 100;
}

/* 圖片設為 100% 填滿容器 */
.card-bg {
  width: 100%;
  height: 100%;
  object-fit: contain; /* 保持圖片比例完整顯示 */
  pointer-events: none;
}

/* 文字層容器 */
.card-content {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

/* --- 下面這些位置你需要根據你的圖片微調 --- */

/* 名稱位置 */
.card-text-name {
  position: absolute;
  top: 1.5%;        /* 根據你的圖片框調整垂直位置 */
  width: 100%;
  text-align: center;
  font-size: 16px;
  font-weight: bold;
  color: #fff;
  text-shadow: 2px 2px 0 #000;
}

/* 費用位置 (原本是左下角) */
.card-text-cost {
  position: absolute;
  bottom: 1%;    /* 這裡要根據你的寶石圖案高度調整 */
  left: 4%;       /* 這裡要根據你的寶石圖案水平位置調整 */
  width: 30px;    /* 限制寬度讓文字置中 */
  text-align: center;
  font-size: 16px;
  font-weight: 900;
  text-shadow: 0 0 4px #000, 2px 2px 0 #000;
}

/* 描述位置 (最下方) */
.card-text-desc {
  position: absolute;
  bottom:   15%;     /* 距離底部的距離 */
  left: 10%;
  width: 80%;
  height: 20%;    /* 描述框的高度 */
  font-size: 12px;
  color: #eee;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1.3;
  text-shadow: 1px 1px 0 #000;
}
</style>