// 套用卡牌效果
// js/systems/applyCardEffect.js
import { drawCards } from "./utils.js";

export function applyCardEffect(player, enemy, card, logFn) {
    console.log(`${player.name} 使用 ${card.name} (Type: ${card.type})`);

    switch (card.type) {
        // --- 攻擊類 (物理/魔法/遠程/帶Debuff) ---
        case "atk":
        case "atk_debuff":
        case "atk_ranged":
        case "atk_magic": {
            // 計算總傷害
            let dmg = card.dmg + (player.buff || 0) + (player.attack || 0);

            // 處理 Debuff
            if (card.type === "atk_debuff" && card.debuff) {
                logFn(`${enemy.name} 被施加了 ${card.debuff} 層負面狀態！`);
            }

            // 扣護甲機制
            let armorLoss = Math.min(enemy.defend, dmg);
            enemy.defend -= armorLoss;
            let actualDmg = dmg - armorLoss;

            actualDmg = Math.max(0, actualDmg);

            // 扣 HP
            if (actualDmg > 0) {
                const hploss = Math.min(actualDmg, enemy.hp);
                enemy.hp -= hploss;
                logFn(`${enemy.name} 受到 ${hploss} 點傷害（剩餘 HP=${enemy.hp}, 護甲=${enemy.defend}）`);
            } else {
                logFn(`${player.name} 的攻擊被護甲完全吸收`);
            }
            break;
        }

        // --- 防禦類 ---
        case "defend":
        case "defend_magic": { // 修正：加上大括號
            // 確保數值存在，預設為 0
            const defAmt = card.def || 0;
            player.defend += defAmt;
            logFn(`${player.name} 獲得 ${defAmt} 護甲（目前護甲=${player.defend}）`);
            break;
        }

        // --- 治療類 ---
        case "heal": { // 習慣上也加上大括號比較保險
            if (player.hp === player.maxHP) {
                logFn(`${player.name} 生命值已滿，無法回復`);
            } else {
                const healAmount = Math.min(card.heal, player.maxHP - player.hp);
                player.hp += healAmount;
                logFn(`${player.name} 回復 ${healAmount} 點生命`);
            }
            break;
        }

        // --- 增益類 (Buff) ---
        case "buff_atk":
        case "buff_attack": { // 習慣上也加上大括號
            const buffValue = card.buff || card.buffDmg || 0;
            player.buff = (player.buff || 0) + buffValue;
            logFn(`${player.name} 攻擊力上升 +${buffValue}`);
            break;
        }

        // --- 抽牌類 ---
        case "draw": { // 修正：加上大括號
            logFn(`${player.name} 發動抽牌效果！`);
            // 預設抽 2 張，除非卡牌有特別寫 drawAmount
            const drawCount = card.drawAmount || 2; 
            drawCards(player, drawCount);
            break;
        }

        default:
            console.warn("未知的卡牌類型:", card.type);
            logFn(`${player.name} 使用了卡牌，但什麼事都沒發生...`);
            break;
    }   
}